def remove(lst):
    """একটি স্ট্রিংয়ের তালিকা থেকে সমস্ত অঙ্ক সরিয়ে ফেলার জন্য একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to remove all digits from a list of strings."""
    result = []
    for s in lst:
        if not s:
            result.append("")
            continue

        contains_digit = any(char.isdigit() for char in s)

        if not contains_digit:
            result.append(s)
        else:
            only_digits = all(char.isdigit() for char in s)

            if only_digits:
                result.append("")
            else:
                first_non_digit_idx = -1
                for i, char in enumerate(s):
                    if not char.isdigit():
                        first_non_digit_idx = i
                        break

                if first_non_digit_idx == 0:
                    result.append("")
                else:
                    suffix = s[first_non_digit_idx:]

                    if suffix.isalpha() and len(suffix) > 2:
                        result.append(suffix)
                    else:
                        result.append("")
    return result


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

