def min_length_list(input_list):
    """ল্যাম্বদা ফাংশন ব্যবহার করে সর্বনিম্ন দৈর্ঘ্যের তালিকাটি খুঁজে পেতে একটি ফাংশন লিখুন।"""
    """Translated: Write a function to find the list with the minimum length using a lambda function."""
    if not input_list:
        return (0, [])

    # Use a lambda function with the min() function to find the sublist with the minimum length
    shortest_sublist = min(input_list, key=lambda x: len(x))
    return (len(shortest_sublist), shortest_sublist)


