def _flip(arr, k):
    start = 0
    while start < k:
        arr[start], arr[k] = arr[k], arr[start]
        start += 1
        k -= 1

def pancake_sort(nums):
    n = len(nums)
    if n <= 1:
        return nums[:]

    arr = nums[:]

    for curr_size in range(n, 1, -1):
        max_val_idx = 0
        for i in range(1, curr_size):
            if arr[i] > arr[max_val_idx]:
                max_val_idx = i

        if max_val_idx != curr_size - 1:
            _flip(arr, max_val_idx)
            _flip(arr, curr_size - 1)

    return arr


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, pancake_sort([15, 79, 25, 38, 69]), [15, 25, 38, 69, 79])
    check(2, pancake_sort([]), [])
    check(3, pancake_sort([5]), [5])
    check(4, pancake_sort([1, 2, 3, 4]), [1, 2, 3, 4])
    check(5, pancake_sort([4, 3, 2, 1]), [1, 2, 3, 4])
    check(6, pancake_sort([3, 1, 4, 1, 5, 9, 2, 6]), [1, 1, 2, 3, 4, 5, 6, 9])
