def count_Primes_nums(n):
    def is_prime(k):
        if k <= 1:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        i = 3
        while i * i <= k:
            if k % i == 0:
                return False
            i += 2
        return True

    count = 0
    for num in range(2, n):
        if is_prime(num):
            count += 1
    return count


