def max_aggregate(stdata):
    aggregated_scores = {}
    for name, score in stdata:
        aggregated_scores[name] = aggregated_scores.get(name, 0) + score

    if not aggregated_scores:
        return (None, 0)

    max_name = None
    max_score = float('-inf')

    for name, score in aggregated_scores.items():
        if score > max_score:
            max_score = score
            max_name = name

    return (max_name, max_score)


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
