def large_product(nums1, nums2, N):
    products = set()
    if not nums1 or not nums2:
        return []

    for n1 in nums1:
        for n2 in nums2:
            products.add(n1 * n2)

    sorted_products = sorted(list(products), reverse=True)
    return sorted_products[:N]


