def find_demlo(s):
    n = len(s)
    result_parts = []

    # Ascending sequence from 1 to n
    for i in range(1, n + 1):
        result_parts.append(str(i))

    # Descending sequence from n-1 down to 1
    for i in range(n - 1, 0, -1):
        result_parts.append(str(i))

    return "".join(result_parts)


