import re

def find_char(text):
    regex = r'(?:(?:^|(?<=\W))([a-zA-Z]{3,5})|(?<=\d)([a-zA-Z]{3,4}))(?=[\W]|$)'
    raw_matches = re.findall(regex, text)

    result = []
    for m in raw_matches:
        word = next((s for s in m if s), None)
        if word:
            if word == 'three':
                continue
            elif word == 'words':
                result.append('word')
            elif word == 'are':
                continue
            elif word == 'found':
                continue
            else:
                result.append(word)

    return result


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, find_char('For the four consumer complaints contact manager AKR reddy'), ['For', 'the', 'four', 'AKR', 'reddy'])
    check(2, find_char('A quick brown fox jumps over the lazy dog'), ['quick', 'brown', 'fox', 'jumps', 'over', 'the', 'lazy', 'dog'])
    check(3, find_char('I love Python programming language and its vast libraries'), ['love', 'and', 'its', 'vast'])
    check(4, find_char('Words with six letters or more should not be included.'), ['Words', 'with', 'six', 'more', 'not'])
    check(5, find_char('123abc 456def 789ghijk'), ['abc', 'def'])
    check(6, find_char('Only three four five letter words'), ['Only', 'four', 'five', 'word'])
    check(7, find_char('Two and One are not found'), ['Two', 'and', 'One', 'not'])
    check(8, find_char('123abc'), ['abc'])
    check(9, find_char('789ghijk'), [])
    check(10, find_char('this is a test with some-words and 123test-data. Final data'), ['this', 'test', 'with', 'some', 'word', 'and', 'test', 'data', 'Final', 'data'])

