def make_flip(ch):
    n = len(ch)

    flips_to_start_0 = 0
    for i in range(n):
        if i % 2 == 0:
            if ch[i] == '1':
                flips_to_start_0 += 1
        else:
            if ch[i] == '0':
                flips_to_start_0 += 1

    flips_to_start_1 = 0
    for i in range(n):
        if i % 2 == 0:
            if ch[i] == '0':
                flips_to_start_1 += 1
        else:
            if ch[i] == '1':
                flips_to_start_1 += 1

    return min(flips_to_start_0, flips_to_start_1)


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

