memo = {}

def breakSum(n):
    if n <= 1:
        return n
    if n in memo:
        return memo[n]

    sum_of_parts = breakSum(n // 2) + breakSum(n // 3) + breakSum(n // 4)

    result = max(n, sum_of_parts)
    memo[n] = result
    return result

