def sort_counter(dict1):
    return sorted(dict1.items(), key=lambda item: item[1], reverse=True)


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sort_counter({'Math': 81, 'Physics': 83, 'Chemistry': 87}), [('Chemistry', 87), ('Physics', 83), ('Math', 81)])
    check(2, sort_counter({'a': 10, 'b': 5, 'c': 15}), [('c', 15), ('a', 10), ('b', 5)])
    check(3, sort_counter({'apple': 3, 'banana': 7, 'orange': 2, 'grape': 5}), [('banana', 7), ('grape', 5), ('apple', 3), ('orange', 2)])
    check(4, sort_counter({'x': 1, 'y': 1, 'z': 1}), [('x', 1), ('y', 1), ('z', 1)]) 
    check(5, sort_counter({}), [])
    check(6, sort_counter({'A': 100, 'B': 90, 'C': 100, 'D': 80}), [('A', 100), ('C', 100), ('B', 90), ('D', 80)]) # Test with duplicate max values

def big_sum(nums):
    if not nums:
        return 0
    return max(nums) + min(nums)


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, big_sum([1, 2, 3]), 4)
    check(2, big_sum([5, 10, 1]), 11)
    check(3, big_sum([-5, 0, 5]), 0)
    check(4, big_sum([7]), 14)
    check(5, big_sum([-10, -20, -5]), -25)
    check(6, big_sum([100, 200, 50, 300]), 350)
    check(7, big_sum([]), 0)
    check(8, big_sum([10, 10, 10]), 20)
    check(9, big_sum([0, 0, 0]), 0)

def remove_lowercase(str1):
    return ''.join([char for char in str1 if not char.islower()])


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, remove_lowercase('PYTHon'), 'PYTH')
    check(2, remove_lowercase('Hello World'), 'H W')
    check(3, remove_lowercase('PYTHON'), 'PYTHON')
    check(4, remove_lowercase('python'), '')
    check(5, remove_lowercase(''), '')
    check(6, remove_lowercase('123ABCdef'), '123ABC')
    check(7, remove_lowercase('aBcDeFg123'), 'BDF123')
    check(8, remove_lowercase('MixedCase123!@#'), 'MC123!@#')

def get_max_occuring_char(str1):
    char_counts = {}
    for char in str1:
        char_counts[char] = char_counts.get(char, 0) + 1

    if not char_counts:
        return ''

    max_count = -1
    max_char = ''
    for char, count in char_counts.items():
        if count > max_count:
            max_count = count
            max_char = char
    return max_char


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, get_max_occuring_char('data'), 'a')
    check(2, get_max_occuring_char('programming'), 'r')
    check(3, get_max_occuring_char('aabbc'), 'a')
    check(4, get_max_occuring_char(''), '')
    check(5, get_max_occuring_char('hello world'), 'l')
    check(6, get_max_occuring_char('aaaaabbc'), 'a')
    check(7, get_max_occuring_char('banana'), 'a')
    check(8, get_max_occuring_char('test string'), 't')

