import math

def area_pentagon(a):
    return (5 * a ** 2) / (4 * math.tan(math.pi / 5))


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, area_pentagon(5), 43.01193501472417)
    check(2, area_pentagon(10), 172.04774005889668)
    check(3, area_pentagon(7), 84.30339262885938)
    check(4, area_pentagon(0), 0.0)
    check(5, area_pentagon(1), 1.720477400588967)

